def get_sql_query_tool_spec() -> dict:
    return {
        "type": "function",
        "name": "run_sql_query",
        "description": "Run a read-only SQL query against database",
        "parameters": {
            "type": "object",
            "properties": {
                "query": {"type": "string", "description": "SQL query to execute"}
            },
            "required": ["query"]
        }
    }
